(function(){
  'use strict';
  const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const s={draft:'',thread:null,threads:[],running:false,steps:[],error:'',canContinue:true,configured:null,jobId:null,aiHealth:null,checkingHealth:false};
  let api,paint,toast;
  const when=v=>String(v||'').replace('T',' ').replace('+08:00','');
  const refs=ids=>(ids||[]).map(id=>`<button class="agent-cite" data-agent="evidence" data-id="${esc(id)}">${esc(id)}</button>`).join(' ');
  const status={running:'调查中','needs-input':'等待补充','evidence-collected':'已整理证据','insufficient-evidence':'证据不足',interrupted:'本轮未完成'};
  function rankings(){const e=[...(s.thread?.evidence||[])].reverse().find(e=>e.success&&['white-screen-ranking','white-screen-distribution'].includes(e.result?.mode));if(!e)return'';const r=e.result;const distribution=r.mode==='white-screen-distribution';const filterNote=Object.entries(r.appliedFilters||e.scope?.filters||{}).map(([key,v])=>key+' '+v.method+' '+(v.values||[]).join(', ')).join('；');if(distribution)return `<section class="agent-card agent-ranking"><div class="row between"><h3>白屏数量及占比分布</h3>${refs([e.id])}</div><p class="agent-muted">${esc(when(r.timeRange?.start))} 至 ${esc(when(r.timeRange?.end))} · 按筛选后的白屏数量排序</p><p>白屏程度：${r.levelCodes?.length?esc(r.levelCodes.join('、'))+'（来自 APM 链接）':'未设置筛选'} · ${r.coverage?.complete?'CLI 查询范围完整':'CLI 查询仅覆盖部分范围'}</p><p class="agent-gap">数据来源：官方 CLI 默认查询通道。${r.requestedDataMode==='preaggregated'?'请求对齐 APM 预聚合数据，当前尚未完成同口径对齐。':'尚未确认与 APM 页面数据模式一致。'}</p><div class="agent-ranking-scroll"><table class="agent-ranking-table"><thead><tr><th>页面</th><th>白屏占比</th><th>白屏数量</th></tr></thead><tbody>${(r.series||[]).map((v,i)=>`<tr><td><span class="agent-ranking-place">${i+1}</span>${esc(v.page)}</td><td><strong>${v.sharePercent==null?'未计算':esc(v.sharePercent)+'%'}</strong></td><td>${esc(v.whiteScreenCount)}</td></tr>`).join('')}</tbody></table></div><p class="agent-muted">白屏占比的分母是所有页面同筛选条件下的白屏总数，${esc(r.totalCount??r.observedCount)} 次；不是页面 PV，也不是页面白屏率。</p>${filterNote?`<details><summary>实际执行的筛选条件</summary><p>${esc(filterNote)}</p></details>`:''}${(r.warnings||[]).map(w=>`<p class="agent-gap">${esc(w)}</p>`).join('')}</section>`;const table=(rows,title)=>`<section><h4>${title}</h4><div class="agent-ranking-scroll"><table class="agent-ranking-table"><thead><tr><th>页面</th><th>白屏率</th><th>白屏次数</th><th>PV</th></tr></thead><tbody>${(rows||[]).map((v,i)=>`<tr><td><span class="agent-ranking-place">${i+1}</span>${esc(v.page)}</td><td><strong>${esc(v.ratePercent)}%</strong></td><td>${esc(v.whiteScreenCount)}</td><td>${esc(v.pageViews)}</td></tr>`).join('')}</tbody></table></div></section>`;return `<section class="agent-card agent-ranking"><div class="row between"><h3>${r.coverage?.complete?'端内白屏页面 Top3':'端内白屏部分窗口排行'}（${filterNote?'已筛选':'未设置白屏程度筛选'}）</h3>${refs([e.id])}</div><p class="agent-muted">${esc(when(r.timeRange?.start))} 至 ${esc(when(r.timeRange?.end))} · 白屏率按总白屏次数 ÷ 总 PV 汇总，已逐段核对 APM 内置率。</p>${filterNote?`<p class="agent-muted">本次筛选：${esc(filterNote)}</p>`:''}${table(r.byRate,'按白屏率排序')}${table(r.byCount,'按白屏次数排序')}<p class="agent-muted">访问量较小的页面，少数事件也可能对应较高白屏率。排行表示 APM 的白屏判定，技术原因需继续核对样本。</p>${(r.warnings||[]).map(w=>`<p class="agent-gap">${esc(w)}</p>`).join('')}</section>`}
  function whitePolicy(){const t=s.thread;if(!t||!(t.evidence||[]).some(e=>['white-screen-ranking','white-screen-distribution'].includes(e.result?.mode)||e.scope?.name==='hybridWhiteScreen'||e.scope?.measurements?.includes('hybridWhiteScreen')))return'';const p=t.whiteScreenPolicy||{};const filtered=[...(t.evidence||[])].reverse().find(e=>e.success&&e.result?.mode==='white-screen-distribution');const levels=filtered?.result?.levelCodes||[];return `<section class="agent-card agent-white-policy"><div class="row between"><h3>白屏排查口径</h3><span class="agent-label">按当前筛选条件统计</span></div><div class="agent-white-priorities"><strong>重点程度</strong><span>完全白屏</span><span>纯色白屏（非白色）</span></div><p class="agent-muted">${levels.length?'已应用链接中的白屏程度筛选：'+esc(levels.join('、'))+'。白屏程度与白屏类型分别保留。':esc(p.typeMappingNote||'尚未应用白屏程度筛选；未筛选排行不能作为这两类的分布。')} ${refs(filtered?[filtered.id]:p.evidenceIds)}</p><details><summary>核验步骤与判断边界</summary><p>先核对截图和页面预期，排除正常背景、加载态、透明弹窗及页面退出；再关联同页同会话的加载、渲染、请求与退出记录。</p><p class="agent-muted">筛选范围之外的数据不能混入当前结论。检测信号、用户可见故障和技术根因需要分别核实。</p></details></section>`}
  function report(){const r=s.thread?.report;if(!r)return'';return `<section class="agent-conclusion"><div class="agent-eyebrow">当前结论 <span>${r.generatedBy==='verified-statistics'?'已核验统计 · 原因分析待完成':'Agent 分析 · 依据见下方引用'}</span></div><h2>${esc(r.title)}</h2><p>${esc(r.summary)}</p><div class="agent-conclusion-meta">${when(r.generatedAt)} · ${s.thread.evidence.filter(x=>x.success).length} 次成功取证 · ${s.thread.rounds.length} 轮调查</div></section>${whitePolicy()}${rankings()}<div class="agent-findings"><section class="agent-card"><h3>已经确认的事实</h3>${(r.facts||[]).map(f=>`<div class="agent-fact"><p>${esc(f.text)}</p>${refs(f.evidenceIds)}</div>`).join('')||'<p class="agent-muted">尚无带有效证据引用的事实。</p>'}</section><section class="agent-card"><h3>还需要验证</h3>${(r.hypotheses||[]).map(f=>`<div class="agent-fact"><span class="agent-label">待验证假设</span><p>${esc(f.text)}</p>${refs(f.evidenceIds)}</div>`).join('')}${(r.gaps||[]).map(g=>`<p class="agent-gap">${esc(g)}</p>`).join('')||'<p class="agent-muted">以当前查询范围为准。</p>'}${(r.nextActions||[]).length?`<h4>下一步</h4><ul>${r.nextActions.map(g=>`<li>${esc(g)}</li>`).join('')}</ul>`:''}</section></div>`}
  function progress(){return `<div class="agent-progress" role="status" aria-live="polite"><div class="row between"><strong>${s.running?'正在调查':'本轮查询过程'}</strong><span class="agent-muted">${s.running?'正在调用实际数据源':'已保留查询记录'}</span></div>${s.steps.slice(-5).map(x=>`<div class="agent-progress-step"><span class="agent-progress-dot"></span><span>${esc(x.title)}</span><time>${when(x.at).slice(11,19)}</time></div>`).join('')}</div>`}
  function followUpHtml(){const thread=s.thread;if(!thread?.followUp)return'';const latest=thread.rounds?.at(-1),needsInput=latest?.status==='needs-input',failure=thread.failure||latest?.failure;const analysis=failure?.service==='analysis'||/Agent.*分析服务|分析服务.*连接|ConnectError/.test(thread.followUp);const quota=failure?.code==='AI_BUDGET_EXHAUSTED'||/HTTP 402|预算已耗尽|预算耗尽|额度已耗尽/.test(thread.followUp);const queried=latest?.steps?.length||0;const health=s.aiHealth;return `<section class="agent-followup"><strong>${needsInput?'还需要你补充':quota?'分析额度不足':analysis?'分析服务连接异常':'调查提示'}</strong><p>${esc(thread.followUp)}</p>${analysis?`${quota?'<p class="agent-muted">此问题无法通过重登数据平台或连续重试解决。恢复项目 AI 额度后，可继续这份调查。</p><p><a class="text-btn" href="https://cowork.xiaohongshu.com/app/NWEyYzVjNDc" target="_blank" rel="noopener noreferrer">打开作品管理 →</a></p>':''}<p class="agent-muted">${queried?'本轮已取得的证据已保留，重试将沿用已有上下文。':'本轮尚未执行平台查询，你的问题已保存。'}无需重新登录数据平台。</p><div class="agent-recovery"><button class="btn primary" data-agent="retry" ${s.running||!s.canContinue?'disabled':''}>${quota?'额度恢复后重试 →':'重试本轮 →'}</button><button class="btn" data-agent="health" ${s.checkingHealth?'disabled':''}>${s.checkingHealth?'正在检测…':'检测分析服务'}</button></div>${health?`<p class="agent-health-status" role="status">${esc(health.message)}</p>`:''}`:needsInput?'':'<button class="text-btn" data-action="connections">检查数据源连接 →</button>'}</section>`}
  function html(){const thread=s.thread;return `<div class="agent-space"><div class="agent-heading"><div><div class="agent-eyebrow">TRACE AGENT</div><h1>${thread?'把调查继续向前推进。':'从一个问题，找到有依据的结论。'}</h1><p>描述现象、贴日志或监控链接。迹线会选择数据源，查询、核对并保留证据。</p></div><button class="btn" data-agent="new" ${s.running?'disabled':''}>＋ 新建调查</button></div>${report()}${followUpHtml()}<form id="agent-form" class="agent-composer"><label for="agent-question">${thread?'补充线索，继续这份调查':'你遇到了什么问题？'}</label><textarea id="agent-question" name="question" rows="5" maxlength="14000" placeholder="例如：帮我查一下 circles 最近 1 小时的 JS 错误，先找主要类型，再选择样本追查原因。\n\n也可以直接粘贴 APM 页面链接、Trace ID 或日志。" ${s.running||!s.canContinue?'disabled':''}>${esc(s.draft)}</textarea><div class="agent-composer-footer"><span>APM · XRAY · Vesta <span class="agent-muted">／ 按当前账号权限查询</span></span><button class="btn primary" type="submit" ${s.running||!s.canContinue?'disabled':''}>${s.running?'正在调查…':thread?'继续调查 →':'开始调查 →'}</button></div>${!s.canContinue?'<p class="agent-muted">这是共享调查，点击“新建调查”可使用你的账号重新查询。</p>':''}${s.configured===false?'<p class="agent-error">Agent 分析服务尚未就绪，请稍后重试。</p>':''}</form>${s.error?`<div class="agent-error" role="alert">${esc(s.error)}</div>`:''}<div id="agent-progress">${s.steps.length||s.running?progress():''}</div>${thread?history()+evidence():`<div class="agent-suggestions"><button data-agent="example" data-value="帮我查一下 circles 最近1小时的JS错误，先核对指标口径，再找主要错误类型并选样本追查。"><strong>错误为何增加</strong><span>从指标走势到具体异常样本</span></button><button data-agent="example" data-value="我遇到了一个页面白屏，想关联页面会话、加载与请求记录。"><strong>页面为什么白屏</strong><span>补充页面或监控链接后追查</span></button><button data-agent="example" data-value="帮我检查 Vesta 回捞任务4621951，是否真正覆盖原来超时的时间，需要哪些信息？"><strong>日志是否覆盖异常</strong><span>区分回捞完成与可用证据</span></button></div><div class="agent-scope">当前可自主查询监控、会话、请求链路与既有回捞日志。源码、发布变更及其他平台需继续接入；不会自动修改线上配置或发起新的回捞任务。</div>`}${recent()}</div>`}
  function history(){return `<section class="agent-card agent-history"><div class="row between"><h3>排查历史</h3><span class="agent-muted">${s.thread.rounds.length} 轮 · 保留每次结论及依据</span></div>${s.thread.rounds.map(r=>`<details ${r.number===s.thread.rounds.length?'open':''}><summary><span class="agent-round-number">${r.number}</span><span>第 ${r.number} 轮 <small>${when(r.startedAt)}</small></span><span class="agent-round-state">${esc(status[r.status]||r.status)}</span></summary><div class="agent-round-body"><p class="agent-muted">${esc(r.question)}</p><p>${esc(r.summary||'正在收集证据。')}</p>${r.steps.map(step=>`<div class="agent-round-step"><span class="agent-label">${esc(step.tool)}</span><span>${esc(step.purpose)}</span><span>${step.success?'已取得结果':'未完成'}</span>${refs([step.evidenceId])}</div>`).join('')}</div></details>`).join('')}</section>`}
  function evidence(){return `<section class="agent-card agent-evidence"><div class="row between"><h3>证据与查询审计</h3><button class="text-btn" data-agent="export">导出调查报告 ↓</button></div><p class="agent-muted">每条引用对应一次实际工具返回。展开查看范围、时间、状态与脱敏数据。</p>${s.thread.evidence.map(e=>`<details id="agent-${esc(e.id)}"><summary><span class="agent-evidence-number">${esc(e.id)}</span><strong>${esc(e.purpose)}</strong><span class="agent-round-state ${e.success?'':'agent-failed'}">${e.success?'查询成功':'查询未完成'}</span></summary><div class="agent-evidence-body"><p>${esc(e.tool)} · ${when(e.queriedAt)}</p>${e.error?`<p class="agent-error">${esc(e.error)}</p>`:''}${e.reachedLimit||e.result?.coveredFullRange===false||e.result?.agentExportTruncated||e.result?.coverage?.complete===false?'<p class="agent-gap">结果可能未覆盖完整范围，不能作为全量统计。</p>':''}<h4>本次查询范围</h4><pre>${esc(JSON.stringify(e.scope,null,2))}</pre>${e.command?`<h4>官方 CLI 命令</h4><pre>${esc(e.command.map(v=>/\s/.test(v)?JSON.stringify(v):v).join(' '))}</pre>`:''}${e.requestId?`<p>查询 Request ID：${esc(e.requestId)}</p>`:''}${e.subqueries?`<h4>分段查询审计</h4><pre>${esc(JSON.stringify(e.subqueries,null,2))}</pre>`:''}${e.success?`<h4>实际返回（已脱敏）</h4><pre>${esc(JSON.stringify(e.result,null,2))}</pre><p class="agent-hash">响应 SHA-256：${esc(e.responseSha256)}</p>`:''}</div></details>`).join('')||'<p class="agent-muted">尚未执行平台查询。</p>'}</section>`}
  function recent(){return `<section class="agent-recent"><h3>工作空间的调查记录</h3>${s.threads.length?`<div class="agent-recent-grid">${s.threads.slice(0,8).map(t=>`<button data-agent="open" data-id="${esc(t.id)}" ${s.running?'disabled':''}><strong>${esc(t.title||'待补充线索')}</strong><span>${t.roundCount} 轮调查 · ${when(t.updatedAt)}</span><span>${t.canContinue?'可继续调查':'共享记录'}</span></button>`).join('')}</div>`:'<p class="agent-muted">新调查将在这里保存，脱敏报告对公司登录用户可见。</p>'}</section>`}
  async function load(){try{const d=await api('agent/threads');s.threads=d.threads||[];paint()}catch(e){s.error=e.message;paint()}}
  async function send(override){const input=document.querySelector('#agent-question');const question=(typeof override==='string'?override:input?.value||s.draft).trim();if(!question||s.running)return;let started;try{s.error='';s.running=true;s.steps=[];s.draft=question;paint();started=await api('agent/run',{method:'POST',body:JSON.stringify({question,...(s.thread?{threadId:s.thread.id}:{})})});s.jobId=started.jobId;for(let count=0;count<600;count++){const job=await api('jobs/'+started.jobId);s.steps=job.steps||[];const target=document.querySelector('#agent-progress');if(target)target.innerHTML=progress();if(job.state==='error')throw new Error(job.error||'本轮调查未完成。');if(job.state==='complete'){s.thread=job.result.thread;s.canContinue=true;s.draft='';s.running=false;paint();await load();return}await new Promise(resolve=>setTimeout(resolve,1000))}throw new Error('等待超时，请稍后在调查记录中查看。')}catch(e){s.error=e.message;s.running=false;if(started?.threadId){try{const d=await api('agent/threads/'+started.threadId);s.thread=d.thread;s.canContinue=d.canContinue}catch{}}paint()}}
  document.addEventListener('input',e=>{if(e.target.id==='agent-question')s.draft=e.target.value});
  document.addEventListener('submit',e=>{if(e.target.id==='agent-form'){e.preventDefault();send()}});
  document.addEventListener('click',async e=>{const b=e.target.closest('[data-agent]');if(!b||b.disabled)return;switch(b.dataset.agent){case'retry':{const q=s.thread?.rounds?.at(-1)?.question;if(q)send(q);break}case'health':{s.checkingHealth=true;s.aiHealth=null;paint();try{s.aiHealth=await api('agent/health')}catch(err){s.aiHealth={message:err.message}}finally{s.checkingHealth=false;paint()}break}case'new':if(s.running)return;s.thread=null;s.draft='';s.error='';s.steps=[];s.aiHealth=null;s.canContinue=true;paint();break;case'example':s.draft=b.dataset.value;paint();document.querySelector('#agent-question')?.focus();break;case'open':try{const d=await api('agent/threads/'+b.dataset.id);s.thread=d.thread;s.canContinue=d.canContinue;s.steps=[];s.error='';s.draft='';paint();window.scrollTo({top:0,behavior:'smooth'})}catch(err){s.error=err.message;paint()}break;case'evidence':{const node=document.getElementById('agent-'+b.dataset.id);if(node){node.open=true;node.scrollIntoView({behavior:'smooth',block:'center'})}break}case'export':{if(!s.thread)return;const r=s.thread.report;const text=['# '+(r?.title||s.thread.title),r?.summary||s.thread.followUp,'## 已确认事实',...(r?.facts||[]).map(f=>'- '+f.text+' ['+f.evidenceIds.join(', ')+']'),'## 证据缺口',...(r?.gaps||[]).map(v=>'- '+v),'## 调查记录与脱敏证据','```json',JSON.stringify(s.thread,null,2),'```'].join('\n\n');const url=URL.createObjectURL(new Blob([text],{type:'text/markdown;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='Trace-Agent-'+s.thread.id+'.md';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);break}}});
  window.TraceAgentUI={html,init(options){api=options.api;paint=options.render;toast=options.toast;load()},setCapabilities(cap){s.configured=cap?.agent?.configured??null},snapshot(){return s}};
})();
